QString TableData::source() const {
    if(rows.isEmpty())return {};if(spans.isEmpty())return tableMarkdown(rows,alignment);QString html="<table>\n";
    for(int r=0;r<rows.size();++r){html+="<tr>";for(int c=0;c<rows[r].size();++c){bool covered=false;TableSpan anchor{r,c,1,1};for(auto span:spans)if(span.contains(r,c)){covered=span.row!=r||span.column!=c;if(!covered)anchor=span;break;}if(covered)continue;QString tag=r==0?"th":"td";html+="<"+tag;if(anchor.rows>1)html+=" rowspan=\""+QString::number(anchor.rows)+"\"";if(anchor.columns>1)html+=" colspan=\""+QString::number(anchor.columns)+"\"";html+=" align=\""+(alignment.value(c)==":---:"?QString("center"):alignment.value(c)=="---:"?QString("right"):QString("left"))+"\" data-mojian-markdown=\""+QString::fromLatin1(rows[r][c].toUtf8().toBase64())+"\">"+Markdown::html(rows[r][c],"extended")+"</"+tag+">";}html+="</tr>\n";}return html+"</table>\n";
}
bool TableData::merge(int r1,int c1,int r2,int c2){if(r1<0||c1<0||r2>=rows.size()||rows.isEmpty()||c2>=rows[0].size()||r2<r1||c2<c1||(r1==0&&r2>0))return false;for(auto span:spans)if(!(span.row+span.rows<=r1||span.row>r2||span.column+span.columns<=c1||span.column>c2))return false;QStringList text;for(int r=r1;r<=r2;++r)for(int c=c1;c<=c2;++c){if(!rows[r][c].isEmpty())text<<rows[r][c];rows[r][c].clear();}rows[r1][c1]=text.join("\n");if(r1!=r2||c1!=c2)spans<<TableSpan{r1,c1,r2-r1+1,c2-c1+1};return true;}
void TableData::split(int row,int column){for(int i=spans.size()-1;i>=0;--i)if(spans[i].contains(row,column))spans.removeAt(i);}
bool TableData::moveRow(int from,int to){if(from<=0||to<=0||from>=rows.size()||to>=rows.size())return false;for(auto span:spans)if(span.rows>1&&(span.contains(from,span.column)||span.contains(to,span.column)))return false;rows.swapItemsAt(from,to);for(auto &span:spans){if(span.row==from)span.row=to;else if(span.row==to)span.row=from;}return true;}
