    QWidget *createEditor(QWidget *parent,const QStyleOptionViewItem &,const QModelIndex &index)const override{auto editor=new Editor(parent);if(auto owner=qobject_cast<Window *>(parent->window()))editor->referenceDefinitions=Markdown::parse(owner->editor->toPlainText(),QSettings().value("dialect","extended").toString())->referenceDefinitions;editor->setObjectName("tableCellEditor");editor->setLive(true);editor->setMinimumHeight(36);QPersistentModelIndex persistent(index);connect(editor,&Editor::sourceChanged,editor,[editor,persistent]{if(editor->composing||!persistent.isValid()||!editor->property("mojianInitialized").toBool())return;editor->setProperty("mojianCommitting",true);const_cast<QAbstractItemModel *>(persistent.model())->setData(persistent,editor->toPlainText(),Qt::EditRole);editor->setProperty("mojianCommitting",false);});return editor;}
