void TableWidget::rebuild(){updating=true;int r=table->currentRow(),c=table->currentColumn();table->clearSpans();table->setRowCount(data.rows.size());table->setColumnCount(data.rows.isEmpty()?0:data.rows[0].size());for(int row=0;row<data.rows.size();++row)for(int column=0;column<data.rows[row].size();++column){auto item=new QTableWidgetItem(data.rows[row][column]);item->setTextAlignment(data.alignment.value(column)==":---:"?Qt::AlignCenter:data.alignment.value(column)=="---:"?Qt::AlignRight|Qt::AlignVCenter:Qt::AlignLeft|Qt::AlignVCenter);table->setItem(row,column,item);}for(auto span:data.spans)table->setSpan(span.row,span.column,span.rows,span.columns);for(int row=0;row<table->rowCount();++row)table->setRowHeight(row,42);if(r>=0&&c>=0)table->setCurrentCell(std::min(r,table->rowCount()-1),std::min(c,table->columnCount()-1));updating=false;}
