    for(auto node:nodes)if(node.type=="text"){QString raw=source.mid(node.start,node.end-node.start);auto matches=encoded.globalMatch(raw);while(matches.hasNext()){auto match=matches.next();QString token=match.captured(),decoded;auto fragment=Markdown::parse("MJI "+token,"commonmark");for(auto part:Markdown::descendants(fragment->root))if(part.type=="text")decoded+=part.literal;if(!decoded.startsWith("MJI "))continue;decoded.remove(0,4);if(decoded==token||decoded.isEmpty())continue;int start=node.start+match.capturedStart();QTextCharFormat format;auto block=editor->document()->findBlock(start);for(auto style:styles.value(block.blockNumber()))if(start-block.position()>=style.start&&start-block.position()<style.start+style.length)format.merge(style.format);QFont font=editor->font();font= format.font().resolve(font);QFontMetricsF metrics(font);QSize size(std::max(1,int(std::ceil(metrics.horizontalAdvance(decoded)))+2),std::max(1,int(std::ceil(metrics.height()))));QImage value(size,QImage::Format_ARGB32_Premultiplied);value.fill(Qt::transparent);QPainter painter(&value);painter.setFont(font);painter.setPen(format.hasProperty(QTextFormat::ForegroundBrush)?format.foreground().color():editor->palette().color(QPalette::Text));painter.drawText(QPointF(0,metrics.ascent()),decoded);painter.end();InlineImage item{start,int(token.size()),value,false};inlineImages<<item;inlineByBlock[block.blockNumber()]<<item;}}
